import { expect, it } from 'vitest';
import type { RepoState } from '../types';
import fixture from './__fixtures__/repo_state.json';
import { splitStatus } from './status';
import { toWipFile } from './wip';

// Generated by src-tauri/tests/contract.rs from a real `repo_state`.
const state = fixture as RepoState;

it('fixture covers every kind of file', () => {
  expect(state.files.map((f) => f.path)).toEqual([
    'both.txt', 'conflicted.txt', 'staged-only.txt', 'untracked.txt', 'worktree-only.txt',
  ]);
});

it('each backend file lands only in the right lists', () => {
  const r = splitStatus(state.files);
  expect(r.staged.map((f) => f.path)).toEqual(['both.txt', 'staged-only.txt']);
  expect(r.unstaged.map((f) => f.path)).toEqual(['both.txt', 'untracked.txt', 'worktree-only.txt']);
  expect(r.conflicted.map((f) => f.path)).toEqual(['conflicted.txt']);
});

it('maps backend files to list rows', () => {
  const r = splitStatus(state.files);
  expect(r.staged.map((f) => toWipFile(f, 'index'))).toEqual([
    { path: 'both.txt', origPath: null, change: 'modified' },
    { path: 'staged-only.txt', origPath: null, change: 'added' },
  ]);
  expect(r.unstaged.map((f) => toWipFile(f, 'worktree'))).toEqual([
    { path: 'both.txt', origPath: null, change: 'modified' },
    { path: 'untracked.txt', origPath: null, change: 'added' },
    { path: 'worktree-only.txt', origPath: null, change: 'modified' },
  ]);
  expect(r.conflicted.map((f) => toWipFile(f, 'worktree'))).toEqual([
    { path: 'conflicted.txt', origPath: null, change: 'modified', conflict: true },
  ]);
});
